from collections import Counter
class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        need = Counter(word2)
        missing = len(need)
        cnt = Counter()
        l = 0
        ans = 0
        for c in word1:
            cnt[c] += 1
            if c in need and cnt[c] == need[c]:
                missing -= 1
            while missing == 0:
                d = word1[l]
                if d in need and cnt[d] == need[d]:
                    break
                cnt[d] -= 1
                l += 1
            if missing == 0:
                ans += l + 1
        return ans

