class Solution {
public:
    long long validSubstringCount(string word1, string word2) {
        long long need[26] = {0}, cnt[26] = {0};
        for (char c : word2) need[c - 'a']++;
        int kinds = 0;
        for (int i = 0; i < 26; i++) if (need[i]) kinds++;
        int have = 0, l = 0;
        long long ans = 0;
        for (char rc : word1) {
            int c = rc - 'a';
            cnt[c]++;
            if (need[c] && cnt[c] == need[c]) have++;
            while (have == kinds) {
                int d = word1[l] - 'a';
                if (need[d] && cnt[d] == need[d]) break;
                cnt[d]--;
                l++;
            }
            if (have == kinds) ans += l + 1;
        }
        return ans;
    }
};

