class Solution {
    public long validSubstringCount(String word1, String word2) {
        long[] need = new long[26], cnt = new long[26];
        for (char c : word2.toCharArray()) need[c - 'a']++;
        int kinds = 0;
        for (int i = 0; i < 26; i++) if (need[i] > 0) kinds++;
        int have = 0, l = 0;
        long ans = 0;
        for (char rc : word1.toCharArray()) {
            int c = rc - 'a';
            cnt[c]++;
            if (need[c] > 0 && cnt[c] == need[c]) have++;
            while (have == kinds) {
                int d = word1.charAt(l) - 'a';
                if (need[d] > 0 && cnt[d] == need[d]) break;
                cnt[d]--;
                l++;
            }
            if (have == kinds) ans += l + 1;
        }
        return ans;
    }
}

