var validSubstringCount = function(word1, word2) {
  const need = new Array(26).fill(0), cnt = new Array(26).fill(0);
  for (const c of word2) need[c.charCodeAt(0) - 97]++;
  let kinds = 0;
  for (let i = 0; i < 26; i++) if (need[i]) kinds++;
  let have = 0, l = 0, ans = 0;
  for (const rc of word1) {
    const c = rc.charCodeAt(0) - 97;
    cnt[c]++;
    if (need[c] && cnt[c] === need[c]) have++;
    while (have === kinds) {
      const d = word1.charCodeAt(l) - 97;
      if (need[d] && cnt[d] === need[d]) break;
      cnt[d]--;
      l++;
    }
    if (have === kinds) ans += l + 1;
  }
  return ans;
};
